<script setup lang="ts">
import type {RegionGroup,Province} from '../types';
import { computed, ref } from 'vue';
import AccessibleDialog from '../../../components/AccessibleDialog.vue';
import { moveProvinces } from '../templateRules';
const props=defineProps<{groups:RegionGroup[];groupIndex:number;provinces:Province[]}>();
const emit=defineEmits<{save:[groups:RegionGroup[]];close:[]}>();
const selected=ref([...props.groups[props.groupIndex].provinces]),name=ref(props.groups[props.groupIndex].name),confirming=ref(false),error=ref('');
const regions=computed(()=>[...new Set(props.provinces.map(p=>p.group))]);
const conflicts=computed(()=>props.groups.flatMap((group,index)=>index===props.groupIndex?[]:group.provinces.filter(code=>selected.value.includes(code)).map(code=>`${props.provinces.find(p=>p.code===code)?.name??code}（原属 ${group.name}）`)));
function toggle(code:string){confirming.value=false;selected.value=selected.value.includes(code)?selected.value.filter(value=>value!==code):[...selected.value,code];}
function quick(codes:string[]){confirming.value=false;selected.value=[...new Set([...selected.value,...codes])];}
function save(confirmed=false){if(!name.value.trim()||!selected.value.length){error.value='请填写地区组名称并选择省份';return;}if(conflicts.value.length&&!confirmed){confirming.value=true;return;}const groups=moveProvinces(props.groups,props.groupIndex,selected.value);groups[props.groupIndex].name=name.value.trim();emit('save',groups);}
</script>
<template><AccessibleDialog :open="true" title="选择指定地区" description="每个省份只能属于一个地区组；跨组移动需确认。" test-id="province-dialog" body-test-id="province-dialog-body" footer-test-id="province-dialog-footer" close-test-id="province-dialog-close" @cancel="emit('close')"><div class="space-y-5"><label class="block text-sm text-slate-600">地区组名称<input v-model="name" class="mt-2 w-full rounded-lg border px-3 py-2" maxlength="100" @input="confirming=false"></label><p v-if="error" role="alert" class="text-sm text-rose-600">{{ error }}</p><div class="flex flex-wrap gap-2 text-xs"><button type="button" class="rounded border px-3 py-1.5 text-indigo-600" @click="quick(provinces.map(p=>p.code))">全国全选</button><button type="button" class="rounded border px-3 py-1.5 text-indigo-600" @click="quick(['310000','320000','330000'].filter(code=>provinces.some(p=>p.code===code)))">江浙沪</button><button type="button" class="rounded border px-3 py-1.5" @click="selected=[];confirming=false">清空选择</button></div><div v-for="region in regions" :key="region" class="flex gap-4 border-t pt-4"><button type="button" class="w-12 shrink-0 self-start pt-1 text-sm font-semibold text-indigo-600" @click="quick(provinces.filter(p=>p.group===region).map(p=>p.code))">{{ region }}</button><div class="grid flex-1 grid-cols-2 gap-3 md:grid-cols-4"><label v-for="province in provinces.filter(p=>p.group===region)" :key="province.code" class="flex items-start gap-2 text-sm text-slate-700"><input :data-testid="`province-${province.code}`" type="checkbox" :checked="selected.includes(province.code)" class="mt-1" @change="toggle(province.code)"><span>{{ province.name }}<small v-if="groups.some((g,i)=>i!==groupIndex&&g.provinces.includes(province.code))" class="block text-amber-700">已属 {{ groups.find((g,i)=>i!==groupIndex&&g.provinces.includes(province.code))?.name }}</small></span></label></div></div><div v-if="confirming" role="alert" class="rounded-lg bg-amber-50 p-4 text-sm text-amber-800"><p class="font-semibold">以下省份已分配，将从原组移动到当前组：</p><p class="mt-2">{{ conflicts.join('、') }}</p><button data-testid="province-move-confirm" type="button" class="mt-3 rounded bg-amber-600 px-4 py-2 text-white" @click="save(true)">确认移动并保存</button></div></div><template #footer><div class="flex items-center justify-between"><span class="text-sm text-slate-500">已选 {{ selected.length }} 个省级地区</span><div class="flex gap-3"><button type="button" class="rounded border px-4 py-2 text-sm" @click="emit('close')">取消</button><button data-testid="province-save" type="button" class="rounded bg-indigo-500 px-4 py-2 text-sm text-white" @click="save()">保存地区组</button></div></div></template></AccessibleDialog></template>
